/**
 * @solidiom/recipes-unocss — UnoCSS recipe profiles for Solidiom primitives.
 *
 * Dual emission:
 *   - Raw stylesheets: importable CSS files targeting data-* semantic attributes,
 *     generated by tools/recipe-emit-unocss.ts from the canonical recipe contract
 *   - TSX wrappers: pre-styled component wrappers composing primitive + stylesheet classes
 *
 * RECIPE-004 closed the gap this package previously declared but did not implement —
 * see git history for the prior `profileStatus = "declared"` stub. `supportedPrimitives`
 * and `implementedRecipes` are now the same list: every primitive this profile intends
 * to cover ships both emission forms.
 */

/** Recipe profile identifier. */
export const recipeProfile = "unocss" as const

/** All primitives with recipe support in this profile. */
export const supportedPrimitives = [
  "dialog",
  "select",
  "button",
  "checkbox",
  "switch",
  "tabs",
  "accordion",
  "popover",
  "tooltip",
  "menu",
  "toast",
  "badge",
  "alert",
] as const

/**
 * Primitives with a shipped UnoCSS recipe in this package.
 *
 * Equal to `supportedPrimitives` now that RECIPE-004 ships every declared primitive.
 * Kept as its own export, rather than an alias, so a future partial regression (a
 * primitive declared but not shipped) is a data change here, not a type change at
 * every call site.
 */
export const implementedRecipes: readonly string[] = supportedPrimitives

// TSX wrapper re-exports (component-shaped recipes)
export { StyledDialog } from "./recipes/dialog"
export { StyledButton, buttonVariants, type ButtonVariantProps } from "./recipes/button"
export { StyledCheckbox } from "./recipes/checkbox"
export { StyledSwitch } from "./recipes/switch"
export { StyledTabs } from "./recipes/tabs"
export { StyledAccordion } from "./recipes/accordion"
export { StyledPopover } from "./recipes/popover"
export { StyledTooltip } from "./recipes/tooltip"
export { StyledMenu } from "./recipes/menu"
export { StyledToast } from "./recipes/toast"
export { StyledSelect } from "./recipes/select"
export { StyledBadge, type BadgeVariant } from "./recipes/badge"
export { StyledAlert, Alert, type AlertVariant } from "./recipes/alert"
